public class Main{
 static long xsNext(long x){x^=x<<13;x^=x>>>7;x^=x<<17;return x;}
 static String genExpr(long seed, boolean corrupt){ long r=seed; char[] ops={'+','-','*','/'}; StringBuilder s=new StringBuilder(); r=xsNext(r); int terms=3+(int)Long.remainderUnsigned(r,4); for(int i=0;i<terms;i++){ if(i>0){r=xsNext(r); s.append(ops[(int)Long.remainderUnsigned(r,4)]);} r=xsNext(r); long n=Long.remainderUnsigned(r,99)+1; s.append(Long.toString(n)); } if(corrupt&&s.length()>4){ s.setCharAt(s.length()/2,'x'); } return s.toString(); }
 static class P{ String s; int i; boolean err; P(String s){this.s=s;} long expr(){ long v=term(); while(!err&&i<s.length()&&(s.charAt(i)=='+'||s.charAt(i)=='-')){ char op=s.charAt(i++); long t=term(); v=(op=='+')?v+t:v-t; } return v; } long term(){ long v=factor(); while(!err&&i<s.length()&&(s.charAt(i)=='*'||s.charAt(i)=='/')){ char op=s.charAt(i++); long f=factor(); if(op=='*') v=v*f; else { if(f==0){err=true;break;} v=v/f; } } return v; } long factor(){ if(i>=s.length()){err=true;return 0;} char c=s.charAt(i); if(c=='('){ i++; long v=expr(); if(i>=s.length()||s.charAt(i)!=')'){err=true;return 0;} i++; return v; } if(c=='-'){ i++; return -factor(); } if(c>='0'&&c<='9'){ long v=0; while(i<s.length()&&s.charAt(i)>='0'&&s.charAt(i)<='9'){ v=v*10+(s.charAt(i)-'0'); i++; } return v; } err=true; return 0; } }
 public static void main(String[]a){ long ok=0,errn=0,total=0; for(long i=0;i<5000;i++){ String s=genExpr(12345+i,i%4==3); P p=new P(s); long v=p.expr(); if(p.err||p.i!=s.length()){errn++;continue;} ok++; total=(total+v)%1000003; if(total<0) total+=1000003; } System.out.println(ok); System.out.println(errn); System.out.println(total); }
}